"""Standalone HTML evidence report. No server, network calls, or payment actions."""
from html import escape as esc
from .engine import money

def render(cases,results):
    sections=[]
    for c,r in zip(cases,results):
        facts=''.join(f'<li><b>{esc(f["code"].replace("_"," "))}</b><p>{esc(f["explanation"])}</p><small>{esc(f["evidence"])}</small></li>' for f in r['findings'])
        base=money(r['base']['minimum_cents']) if r['base'] else 'Not assessed'
        stress=money(r['stress']['minimum_cents']) if r['stress'] else 'Not assessed'
        sections.append(f"""<article id="{esc(r['case_id'])}"><div class="casehead"><span class="status {r['status']}">{r['status']}</span><span class="caseid">{esc(r['case_id'])}</span></div><h2>{esc(r['title'])}</h2><p class="amount">{money(c['invoice']['amount_cents'])} <span>{esc(c['invoice']['currency'])}</span></p><div class="cash"><div><small>BASE MINIMUM CASH</small><strong>{base}</strong></div><div><small>WITHOUT UNCONFIRMED RECEIPTS</small><strong>{stress}</strong></div></div><ul>{facts}</ul><p class="action">{esc(r['next_action'])}</p></article>""")
    return """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FINALITY | Payment review evidence</title><style>
:root{--ink:#101b2b;--muted:#647080;--paper:#f6f5f0;--line:#dce1df;--mint:#67e2c0}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#0b1323;color:#f6f5f0;padding:48px max(6vw,24px) 55px}.wordmark{font-size:19px;letter-spacing:5px;font-weight:800}.meta{float:right;color:#aab6c7;font-size:12px;letter-spacing:1px}h1{font-size:clamp(38px,5vw,66px);letter-spacing:-2.5px;line-height:1.04;font-weight:650;max-width:820px;margin:43px 0 20px}header p{color:#b5c0cf;max-width:680px;font-size:18px;line-height:1.6}.accent{color:var(--mint)}main{max-width:1320px;margin:auto;padding:32px 5vw 64px}.intro{display:flex;gap:45px;justify-content:space-between;align-items:start;margin:0 0 32px}.intro p{font-size:14px;line-height:1.7;max-width:690px;color:var(--muted)}.legend{font-size:13px;line-height:1.9;min-width:185px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}article{background:white;border:1px solid var(--line);padding:28px 30px;break-inside:avoid}.casehead{display:flex;justify-content:space-between;align-items:center;gap:10px}.caseid{font-size:11px;color:var(--muted);letter-spacing:.8px}.status{font-size:11px;font-weight:800;letter-spacing:1.1px;padding:6px 9px;display:inline-block}.READY{background:#dbf8ec;color:#13634a}.HOLD{background:#fff0d4;color:#79530c}.BLOCK{background:#fbe2e2;color:#932e2e}.REVIEW{background:#e5eafb;color:#354d99}h2{font-size:23px;line-height:1.2;letter-spacing:-.6px;margin:23px 0 12px}.amount{font-size:32px;font-weight:650;letter-spacing:-1px;margin:0 0 25px}.amount span{font-size:12px;letter-spacing:1px;color:var(--muted)}.cash{display:flex;gap:24px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:18px 0;margin-bottom:20px}.cash div{flex:1}.cash small{display:block;font-size:9px;letter-spacing:.7px;min-height:24px;color:var(--muted)}.cash strong{font-size:19px}.action{font-size:13px;line-height:1.5;color:#33465b;border-top:1px solid var(--line);padding-top:16px}ul{padding-left:17px;margin:0}li{margin:0 0 18px}li b{font-size:11px;letter-spacing:.7px}li p{font-size:14px;line-height:1.5;margin:6px 0}li small{color:var(--muted);font-size:11px;line-height:1.5;display:block}footer{font-size:12px;color:var(--muted);line-height:1.7;margin-top:32px}@media(max-width:760px){.grid{grid-template-columns:1fr}.intro{display:block}.meta{float:none;display:block;margin-top:12px}article{padding:24px}h1{letter-spacing:-1.5px}}@media print{header{padding:24px}main{padding:20px}.grid{display:block}article{margin-bottom:20px}h1{font-size:42px}}
</style><header><span class="wordmark">FINALITY</span><span class="meta">MIDPOINT PROTOTYPE / OCTOBER 2026</span><h1>A clear decision<br><span class="accent">before money moves.</span></h1><p>Supplier evidence, company rules, and cash consequences in one payment review.</p></header><main><section class="intro"><p><b>Working deterministic simulation.</b> Seven independent scenarios use fictional records and USD amounts. Cash results show scheduled arithmetic and an uncertainty stress case. AI agents, statistical forecasts, manager approvals, and payment execution are planned.</p><div class="legend">READY &nbsp; checks passed<br>REVIEW &nbsp; manager attention<br>HOLD &nbsp; resolve an exception<br>BLOCK &nbsp; already-paid invoice</div></section><section class="grid">"""+''.join(sections)+"""</section><footer>All scenarios share a $5,000 configured cash reserve. Each runs independently against its own starting state. No funds move and no shared cash reservation occurs. Source inputs: data/scenarios.json. Findings reference explicit evidence rather than a generated confidence score.</footer></main></html>"""
